#include <iostream>

int main() {
    long long bytes{2050};
    long long blockBytes{1024};
    // Scaffold from Module 1: reject invalid bounds before division.
    if (bytes < 0 || bytes > 1'000'000'000'000LL || blockBytes < 1 || blockBytes > 4096) {
        std::cout << "invalid\n";
        return 0;
    }
    long long fullBlocks = bytes / blockBytes;
    std::cout << "full=" << fullBlocks << '\n';
    return 0;
}
